import RedisMock from 'ioredis-mock';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
import { Algorithm, MemoryRateLimiter, RateLimiter, RedisRateLimiter } from '../src';

// testdata/vectors.json is generated by the Go test suite
// (go test -run TestParity -update) and pins the exact behaviour of both
// algorithms. Passing it here proves Go and Node.js agree bit for bit.
interface Vectors {
  cases: {
    name: string;
    algorithm: 'gcra' | 'sw';
    limit: number;
    period_us: number;
    steps: {
      key: string;
      now_us: number;
      cost: number;
      allowed: boolean;
      remaining: number;
      retry_after_us: number;
      reset_after_us: number;
    }[];
  }[];
}

const vectors: Vectors = JSON.parse(
  readFileSync(join(__dirname, '..', '..', 'testdata', 'vectors.json'), 'utf8'),
);

const ALGORITHMS: Record<string, Algorithm> = { gcra: 'gcra', sw: 'sliding-window' };

describe('parity with the Go implementation', () => {
  const redis = new RedisMock();
  afterAll(() => redis.disconnect());

  it('has vectors', () => {
    expect(vectors.cases.length).toBeGreaterThan(0);
  });

  describe.each(vectors.cases.map((c) => [c.name, c] as const))('%s', (_name, vc) => {
    const backends: [string, (clock: () => number) => RateLimiter][] = [
      ['memory', (clock) => new MemoryRateLimiter({ algorithm: ALGORITHMS[vc.algorithm], clock })],
      ['redis', (clock) => new RedisRateLimiter(redis, { algorithm: ALGORITHMS[vc.algorithm], clock })],
    ];

    it.each(backends)('%s', async (_backend, make) => {
      await redis.flushall();
      let now = 0;
      const limiter = make(() => now / 1000);
      const spec = { limit: vc.limit, period: vc.period_us / 1000 };
      for (const [i, s] of vc.steps.entries()) {
        now = s.now_us;
        const r = await limiter.allow(s.key, spec, s.cost);
        const got = {
          step: i,
          allowed: r.allowed,
          remaining: r.remaining,
          retry_after_us: Math.round(r.retryAfterMs * 1000),
          reset_after_us: Math.round(r.resetAfterMs * 1000),
        };
        expect(got).toEqual({
          step: i,
          allowed: s.allowed,
          remaining: s.remaining,
          retry_after_us: s.retry_after_us,
          reset_after_us: s.reset_after_us,
        });
      }
    });
  });
});
